381	    /**
382	     * Returns the {@code Idempotency-Key} header of the current request, or {@code null} when the
383	     * header is absent, blank, or there is no bound request. Read from the request context so the
384	     * generated {@link OwnersApi#addOwner} signature is left untouched.
385	     */
386	    private static String idempotencyKey() {
387	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
388	            return null;
389	        }
390	        String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
391	        return isBlank(key) ? null : key;
392	    }
